#include "portfolio.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static Asset defaults[]={{"RELIANCE",1500,12,5,1,1},{"TCS",3200,15,4,2,1},{"INFY",1400,11,3,2,1},{"HDFCBANK",1700,10,2,3,1},{"ICICIBANK",1200,13,4,3,1},{"ITC",450,8,2,4,1},{"SBIN",800,14,6,3,1},{"WIPRO",550,9,3,2,1},{"TATAMOTORS",950,16,7,5,1},{"BHARTIARTL",1600,12,3,6,1}};
static double elapsed(clock_t a,clock_t b){return 1000.0*(double)(b-a)/CLOCKS_PER_SEC;}
static int get_assets(Asset*a){int n=load_assets_csv("data/assets.csv",a,MAX_ASSETS);if(n<=0){n=(int)(sizeof(defaults)/sizeof(defaults[0]));memcpy(a,defaults,sizeof(defaults));}return n;}
static int compare(Asset*a,int n,int budget,int risk,StrategyResult*r){clock_t s,e;Portfolio p;s=clock();p=portfolio_greedy(a,n,budget,risk);e=clock();r[0]=(StrategyResult){"Greedy Heuristic",p,elapsed(s,e),(size_t)n*sizeof(int),0};s=clock();p=portfolio_dp(a,n,budget,risk);e=clock();r[1]=(StrategyResult){"Dynamic Programming",p,elapsed(s,e),(size_t)(n+1)*(size_t)(budget+1)*(size_t)(risk+1)*sizeof(int),1};s=clock();p=portfolio_bnb(a,n,budget,risk,0);e=clock();r[2]=(StrategyResult){"B&B FIFO",p,elapsed(s,e),(size_t)n*sizeof(Asset)*256,1};s=clock();p=portfolio_bnb(a,n,budget,risk,1);e=clock();r[3]=(StrategyResult){"B&B LIFO",p,elapsed(s,e),(size_t)n*sizeof(Asset)*256,1};s=clock();p=portfolio_bnb(a,n,budget,risk,2);e=clock();r[4]=(StrategyResult){"B&B Least Cost",p,elapsed(s,e),(size_t)n*sizeof(Asset)*256,1};return 5;}
static void show_compare(Asset*a,int n,int budget,int risk){StrategyResult r[5];int i,c=compare(a,n,budget,risk,r);printf("\n%-22s %-8s %-8s %-8s %-10s %-8s\n","Strategy","Cost","Return","Risk","Time(ms)","Exact");for(i=0;i<c;i++)printf("%-22s %-8d %-8d %-8d %-10.4f %-8s\n",r[i].name,r[i].portfolio.cost,r[i].portfolio.return_score,r[i].portfolio.risk,r[i].time_ms,r[i].exact?"Yes":"No");for(i=0;i<c;i++)print_portfolio(r[i].name,a,r[i].portfolio);}
static void portfolio_menu(Asset*a,int n){int b,r;printf("\nPORTFOLIO ANALYSIS\nBudget: ");if(scanf("%d",&b)!=1)return;printf("Maximum risk: ");if(scanf("%d",&r)!=1)return;if(b<=0||r<0){printf("Invalid constraints\n");return;}show_compare(a,n,b,r);}
static void asset_menu(Asset*a,int n){Asset x[MAX_ASSETS];char s[64];memcpy(x,a,(size_t)n*sizeof(Asset));merge_sort_assets(x,n);printf("\nSORTED ASSETS USING MERGE SORT\n");print_assets(x,n);printf("\nStock symbol to search: ");if(scanf("%63s",s)!=1)return;printf("Iterative Binary Search index: %d\n",binary_search_iterative(x,n,s));printf("Recursive Binary Search index: %d\n",binary_search_recursive(x,0,n-1,s));memcpy(x,a,(size_t)n*sizeof(Asset));quick_sort_assets(x,n);printf("Quick Sort verification: %s\n",binary_search_iterative(x,n,s)>=0?"PASS":"Symbol not present");}
static void scenarios(Asset*a,int n){printf("\nSCENARIO 1: NORMAL OPERATION\nBudget 10000, Risk 20\n");show_compare(a,n,10000,20);printf("\nSCENARIO 2: CONSTRAINT SHOCK\nBudget 5000, Risk 10\n");show_compare(a,n,5000,10);printf("\nSCENARIO 3: LARGE DATA STRESS\n");int N=50000,i;Asset*x=malloc((size_t)N*sizeof(Asset));if(!x){printf("Allocation failed\n");return;}for(i=0;i<N;i++){snprintf(x[i].symbol,MAX_NAME,"S%06d",N-i);x[i].price=100+i%5000;x[i].return_score=1+i%25;x[i].risk=1+i%10;x[i].sector=i%8;x[i].transaction_limit=1;}clock_t s=clock();merge_sort_assets(x,N);clock_t e=clock();printf("Records: %d, Merge Sort: %.3f ms\n",N,elapsed(s,e));for(i=0;i<N;i++)snprintf(x[i].symbol,MAX_NAME,"S%06d",N-i);s=clock();quick_sort_assets(x,N);e=clock();printf("Records: %d, Quick Sort: %.3f ms\n",N,elapsed(s,e));free(x);}
static void lab(void){int arr[]={-2,1,-3,4,-1,2,1,-5,4};int cm[]={0,1,1,0,0,1,0,0,0};int A[]={1,2,3,4},B[]={5,6,7,8},C[4],D[4];int st[]={1,3,0,5,8,5},fn[]={2,4,6,7,9,9};int freq[]={5,9,12,13,16,45};int g[]={0,2,0,6,0,2,0,3,8,5,0,3,0,0,7,6,8,0,0,9,0,5,7,9,0};int dist[5];int w[]={10,20,30},v[]={60,100,120};int dims[]={40,20,30,10,30};int of[]={34,8,50};int edges[]={0,1,-1,0,2,4,1,2,3,1,3,2,1,4,2,3,2,5,3,1,1,4,3,-3};int fd[]={0,5,999999,10,999999,0,3,999999,999999,999999,0,1,999999,999999,999999,0};int tg[]={0,10,15,20,10,0,35,25,15,35,0,30,20,25,30,0};int ss[]={3,34,4,12,5,2};int flow[]={0,16,13,0,0,0,0,0,10,12,0,0,0,4,0,0,14,0,0,0,9,0,0,20,0,0,0,7,0,4,0,0,0,0,0,0};int bg[]={1,1,0,1,0,1,0,1,1};long long rem[]={2,3,2},mod[]={3,5,7};matrix_multiply_classic(A,B,C,2);matrix_multiply_strassen(A,B,D,2);dijkstra(g,5,0,dist);floyd_warshall(fd,4);printf("\nALGORITHM LAB\n");printf("Maximum Subarray: %d\n",maximum_subarray(arr,9));printf("Fast Power 2^10: %lld\n",fast_power(2,10));printf("Celebrity: %d\n",celebrity(cm,3));printf("Classical/Strassen matrix [0][0]: %d/%d\n",C[0],D[0]);printf("Activity Selection: %d\n",activity_selection(st,fn,6));printf("Interval Partitioning: %d\n",interval_partitioning(st,fn,6));printf("Huffman weighted path length: %d\n",huffman_weighted_path_length(freq,6));printf("Dijkstra 0->4: %d\n",dist[4]);printf("Prim/Kruskal MST: %d/%d\n",prim_mst(g,5),kruskal_mst(g,5));printf("0/1 Knapsack: %d\n",knapsack01(w,v,3,50));printf("Matrix Chain: %lld\n",matrix_chain(dims,5));printf("LCS: %d\n",lcs_length("AGGTAB","GXTXAYB"));printf("Optimal BST: %d\n",optimal_bst_cost(of,3));printf("Bellman-Ford valid: %d\n",bellman_ford(edges,8,5,0,dist));printf("Floyd-Warshall 0->3: %d\n",fd[3]);printf("TSP: %d\n",tsp_bounded(tg,4));printf("N-Queens n=4: %d\n",nqueens_count(4));printf("Subset Sum 9: %d\n",subset_sum(ss,6,9));printf("Ford-Fulkerson Max Flow: %d\n",ford_fulkerson(flow,6,0,5));printf("Bipartite Matching: %d\n",bipartite_matching(bg,3,3));printf("CRT: %lld\n",crt(rem,mod,3));printf("String matches N/RK/FA/KMP: %d/%d/%d/%d\n",naive_match_count("ABABDABACDABABCABAB","ABAB"),rabin_karp_count("ABABDABACDABABCABAB","ABAB"),finite_automaton_count("ABABDABACDABABCABAB","ABAB"),kmp_count("ABABDABACDABABCABAB","ABAB"));}
static void export_menu(Asset*a,int n){int b,r;StrategyResult x[5];printf("Budget: ");if(scanf("%d",&b)!=1)return;printf("Maximum risk: ");if(scanf("%d",&r)!=1)return;if(b<=0||r<0){printf("Invalid constraints\n");return;}compare(a,n,b,r,x);if(export_comparison_csv("output/portfolio_comparison.csv",x,5)&&export_comparison_json("output/portfolio_comparison.json",x,5,a))printf("Exported output/portfolio_comparison.csv and output/portfolio_comparison.json\n");else printf("Export failed. Run from the project root and ensure output exists.\n");}
int main(void){Asset a[MAX_ASSETS];int n=get_assets(a),choice=-1;if(!validate_assets(a,n)){printf("Asset validation failed\n");return 1;}while(choice!=0){printf("\nStock Portfolio Selection and Risk Analysis Lab\n1 Portfolio Analysis\n2 Asset Sorting and Searching\n3 Financial Demonstration Scenarios\n4 Algorithm Laboratory\n5 Export Portfolio Comparison\n6 View Assets\n0 Exit\nChoice: ");if(scanf("%d",&choice)!=1)break;switch(choice){case 1:portfolio_menu(a,n);break;case 2:asset_menu(a,n);break;case 3:scenarios(a,n);break;case 4:lab();break;case 5:export_menu(a,n);break;case 6:print_assets(a,n);break;case 0:break;default:printf("Invalid choice\n");}}return 0;}
